#!/usr/bin/env python3
"""Residents survey tables: python3 crosstabs.py INPUT_DIR OUTPUT_FILE

Implements the rules in /app/docs (exports, codebook, cleaning, weighting,
tables, output).  Standard library only.
"""
import csv
import io
import json
import os
import sys
from datetime import datetime, timedelta, timezone
from fractions import Fraction

DELIMS = (",", ";", "\t")


# ----------------------------------------------------------------- exports
def read_export(path):
    with open(path, "rb") as f:
        raw = f.read()
    text = raw.decode("utf-8-sig")
    end = len(text)
    for i, ch in enumerate(text):
        if ch in "\r\n":
            end = i
            break
    header_line = text[:end]
    delim = ","
    for d in DELIMS:
        if d in header_line:
            delim = d
            break
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delim, quotechar='"')
    header = None
    rows = []
    for cells in reader:
        cells = [c.strip() for c in cells]
        if header is None:
            if not any(cells):
                continue
            header = cells
            continue
        if not any(cells):
            continue
        row = {}
        for i, name in enumerate(header):
            if name in row:
                continue
            row[name] = cells[i] if i < len(cells) and cells[i] != "" else None
        rows.append(row)
    return rows


def read_all_exports(indir):
    d = os.path.join(indir, "exports")
    rows = []
    if not os.path.isdir(d):
        return rows
    for name in sorted(os.listdir(d)):
        p = os.path.join(d, name)
        if name.endswith(".csv") and os.path.isfile(p):
            rows.extend(read_export(p))
    return rows


# ------------------------------------------------------------------ parsing
def parse_offset(s):
    sign = -1 if s[0] == "-" else 1
    hh, mm = s[1:].split(":")
    return timedelta(hours=int(hh), minutes=int(mm)) * sign


def parse_time(value, meta):
    if value is None:
        return datetime.min.replace(tzinfo=timezone.utc)
    if meta.get("submitted_format") == "local":
        dt = datetime.fromisoformat(value.replace("T", " "))
        off = parse_offset(meta.get("utc_offset", "+00:00"))
        return (dt - off).replace(tzinfo=timezone.utc)
    dt = datetime.fromisoformat(value)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def parse_duration(value, meta):
    if value is None:
        return None
    if meta.get("duration_format") == "clock":
        parts = [int(p) for p in value.split(":")]
        sec = 0
        for p in parts:
            sec = sec * 60 + p
        return Fraction(sec)
    return Fraction(value)


def parse_int(value, default=0):
    if value is None:
        return default
    try:
        return int(value)
    except ValueError:
        return int(float(value))


# ------------------------------------------------------------------ answers
def question_options(q):
    return q.get("bands") if q["type"] == "age" else q.get("options", [])


def recode_value(entry, value):
    rc = entry.get("recode")
    if rc is None:
        return parse_int(value)
    if value in rc:
        return rc[value]
    # tolerate numeric text such as "3" vs keys written differently
    return rc[str(value)]


def read_answer(q, entry, row, cb):
    """Returns the valid answer: a code, a frozenset of codes, or None."""
    typ = q["type"]
    if typ == "single":
        v = row.get(entry["column"])
        if v is None:
            return None
        code = recode_value(entry, v)
        missing = {o["code"] for o in q["options"] if o.get("missing")}
        return None if code in missing else code
    if typ == "age":
        v = row.get(entry["column"])
        if v is None:
            return None
        src = entry.get("source")
        if src == "band":
            code = recode_value(entry, v)
            return code
        age = parse_int(v)
        if src == "birth_year":
            age = int(cb["reference_date"][:4]) - age
        for b in q["bands"]:
            if b["min"] <= age <= b["max"]:
                return b["code"]
        return None
    # multi
    chosen = set()
    if "columns" in entry:
        for code, col in entry["columns"].items():
            if row.get(col) == "1":
                chosen.add(int(code))
    else:
        v = row.get(entry["column"])
        if v is not None:
            sep = entry["separator"]
            for el in v.split(sep):
                el = el.strip()
                if el == "":
                    continue
                chosen.add(recode_value(entry, el))
    if not chosen:
        return None
    excl = {o["code"] for o in q["options"] if o.get("exclusive")}
    non_ex = {c for c in chosen if c not in excl}
    if non_ex != chosen:
        if non_ex:
            chosen = non_ex
        elif len(chosen) >= 2:
            return None
    missing = {o["code"] for o in q["options"] if o.get("missing")}
    chosen = {c for c in chosen if c not in missing}
    if not chosen:
        return None
    return frozenset(chosen)


def answer_in(ans, codes):
    if ans is None:
        return False
    if isinstance(ans, frozenset):
        return any(c in ans for c in codes)
    return ans in codes


def respondent_answers(rec, cb, qmap):
    """Returns {qid: (asked, valid answer or None)}."""
    row, ver, complete, last_page = rec["row"], rec["version"], rec["complete"], rec["last_page"]
    result = {}
    in_progress = set()

    def resolve(qid):
        if qid in result:
            return result[qid]
        if qid in in_progress or qid not in qmap:
            return (False, None)
        in_progress.add(qid)
        q = qmap[qid]
        entry = q["versions"].get(ver)
        asked = entry is not None
        if asked and not complete and not (entry["page"] <= last_page):
            asked = False
        if asked and q.get("ask_if"):
            ai = q["ask_if"]
            a_asked, a_ans = resolve(ai["question"])
            asked = a_asked and answer_in(a_ans, ai["codes"])
        ans = read_answer(q, entry, row, cb) if asked else None
        in_progress.discard(qid)
        result[qid] = (asked, ans)
        return result[qid]

    for q in cb["questions"]:
        resolve(q["id"])
    return result


# ----------------------------------------------------------------- weighting
def rake(answers, wt):
    n = len(answers)
    w = [1.0] * n
    if n == 0:
        return w
    dims = []
    for d in wt["dimensions"]:
        qid = d["question"]
        present = {a[qid][1] for a in answers if a[qid][1] is not None}
        targets = {}
        for k, v in d["targets"].items():
            if int(k) in present:
                targets[int(k)] = float(v)
        total = sum(targets.values())
        if not targets:
            continue
        shares = {c: (t / total if total else 0.0) for c, t in targets.items()}
        cat = [a[qid][1] if a[qid][1] in shares else None for a in answers]
        dims.append((shares, cat))
    tol = wt.get("tolerance", 1e-10)
    for _ in range(int(wt.get("max_iterations", 100))):
        within = True
        for shares, cat in dims:
            T = 0.0
            Wc = {c: 0.0 for c in shares}
            for i, c in enumerate(cat):
                if c is not None:
                    T += w[i]
                    Wc[c] += w[i]
            f = {}
            for c, s in shares.items():
                f[c] = s * T / Wc[c] if Wc[c] else 1.0
                if abs(f[c] - 1) > tol:
                    within = False
            for i, c in enumerate(cat):
                if c is not None:
                    w[i] *= f[c]
        if within:
            break
    m = sum(w) / n
    hi, lo = wt["cap"] * m, wt["floor"] * m
    w = [min(max(x, lo), hi) for x in w]
    m2 = sum(w) / n
    if m2:
        w = [x / m2 for x in w]
    return w


# ------------------------------------------------------------------- main
def r2(x):
    return round(x, 2) + 0.0


def main(indir, outfile):
    def load(name):
        with open(os.path.join(indir, name), encoding="utf-8-sig") as f:
            return json.load(f)

    cb = load("codebook.json")
    wt = load("weighting.json")
    plan = load("tables.json")
    qmap = {q["id"]: q for q in cb["questions"]}
    vkeys = list(cb["versions"].keys())
    min_page = cb.get("partial_min_page", 0)

    # step 1: rows
    recs = []
    for row in read_all_exports(indir):
        ver = row.get("form_version")
        if ver not in cb["versions"]:
            continue
        meta = cb["versions"][ver]["meta"]
        complete = row.get(meta["status"]) == meta["complete"]
        recs.append({
            "row": row, "version": ver, "complete": complete,
            "id": row.get(meta["id"]),
            "time": parse_time(row.get(meta["submitted"]), meta),
            "duration": parse_duration(row.get(meta["duration"]), meta) if complete else None,
            "last_page": parse_int(row.get(meta["last_page"]), 0),
        })
    stats = {v: {"version": v, "rows": 0, "duplicates": 0, "short_partials": 0,
                 "speeders": 0, "complete": 0, "partial": 0} for v in vkeys}
    for r in recs:
        stats[r["version"]]["rows"] += 1

    # step 2: duplicates
    best = {}
    for r in recs:
        cur = best.get(r["id"])
        if cur is None or (r["complete"], r["time"]) > (cur["complete"], cur["time"]):
            best[r["id"]] = r
    kept = []
    for r in recs:
        if best[r["id"]] is r:
            kept.append(r)
        else:
            stats[r["version"]]["duplicates"] += 1

    # step 3: short partials
    kept2 = []
    for r in kept:
        if not r["complete"] and r["last_page"] < min_page:
            stats[r["version"]]["short_partials"] += 1
        else:
            kept2.append(r)
    kept = kept2

    # speeders
    medians = {}
    for v in vkeys:
        ds = sorted(r["duration"] for r in kept if r["version"] == v and r["complete"])
        if ds:
            k = len(ds)
            medians[v] = ds[k // 2] if k % 2 else (ds[k // 2 - 1] + ds[k // 2]) / 2
    kept3 = []
    for r in kept:
        if r["complete"] and r["duration"] * 5 < medians[r["version"]] * 2:
            stats[r["version"]]["speeders"] += 1
        else:
            kept3.append(r)
    kept = kept3
    for r in kept:
        stats[r["version"]]["complete" if r["complete"] else "partial"] += 1

    # step 4/5: answers and weights
    answers = [respondent_answers(r, cb, qmap) for r in kept]
    weights = rake(answers, wt)
    n = len(kept)

    summary = {"versions": [stats[v] for v in vkeys], "respondents": n,
               "effective_n": None, "weight_min": None, "weight_max": None}
    if n:
        s1 = sum(weights)
        s2 = sum(x * x for x in weights)
        summary["effective_n"] = r2(s1 * s1 / s2) if s2 else None
        summary["weight_min"] = r2(min(weights))
        summary["weight_max"] = r2(max(weights))

    # step 6: tables
    columns = [("total", None, None)]
    for bq in plan["banner"]:
        for o in question_options(qmap[bq]):
            if not o.get("missing"):
                columns.append((f"{bq}:{o['code']}", bq, o["code"]))

    tables = []
    for t in plan["tables"]:
        q = qmap[t["question"]]
        opts = [o for o in question_options(q) if not o.get("missing")]
        scores = {o["code"]: o.get("score") for o in opts}
        base_idx = [i for i in range(n)
                    if answers[i][q["id"]][0] and answers[i][q["id"]][1] is not None]
        cols = []
        for cid, bq, bcode in columns:
            idx = [i for i in base_idx if bq is None or answers[i][bq][1] == bcode]
            wb = sum(weights[i] for i in idx)
            values = {}

            def pct(pred):
                if not idx or not wb:
                    return None
                return r2(100.0 * sum(weights[i] for i in idx if pred(answers[i][q["id"]][1])) / wb)

            for o in opts:
                c = o["code"]
                values[str(c)] = pct(lambda a, c=c: answer_in(a, [c]))
            for net in t.get("nets", []):
                codes = net["codes"]
                values[net["id"]] = pct(lambda a, codes=codes: answer_in(a, codes))
            if t.get("mean"):
                if not idx or not wb:
                    values["mean"] = None
                else:
                    values["mean"] = r2(sum(weights[i] * scores[answers[i][q["id"]][1]] for i in idx) / wb)
            cols.append({"column": cid, "base": len(idx),
                         "weighted_base": r2(wb) if idx else 0, "values": values})
        tables.append({"table": t["id"], "columns": cols})

    out = {"survey": cb["survey"], "summary": summary, "tables": tables}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(out, f, indent=1)
        f.write("\n")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: crosstabs.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])
